Definition copy_run_spec : Prop :=
  forall (mem0 : word -> option byte) (sp ra : word) (pd ps n s : Z) (bs : list byte) (kS fS lS kD fD lD : Z),
    U sp = s -> fS = Eb0RegionPoisoned.SB + ps / 8 -> lS = Eb0RegionPoisoned.SB + (ps + n - 1) / 8 ->
